fn exact_duplicate_guard_allows_only_gain_and_preserves_disabled_boundaries() {
    let (job, layout) = equal_inventory_fixture(false);
    for seed in 0..4 {
        for (enabled, expired) in [(true, false), (false, false), (true, true)] {
            let (moved, after, stats) = exercise(&job, &layout, seed, enabled, expired, 0);
            eprintln!(
                "EXACT_REJECT_WITNESS {}",
                serde_json::json!({
                    "job":&job,"before":&layout,"after":&after,"seed":seed,
                    "enabled":enabled,"expired":expired,"moved":moved,"stats":&stats
                })
            );
            assert_free_return_outcome(&job, &layout, &after, moved, &stats, enabled, expired);
            if enabled && !expired {
                assert!(
                    stats.exact_state_exchange_rejections <= stats.neutral_exchange_rejections
                );
            } else {
                assert_eq!(stats.exact_state_exchange_rejections, 0);
                assert_eq!(stats.directed_exchange_attempts, 0);
            }
        }
    }
}

